// Detect long tasks in the field and log the worst offenders.
try {
  const observer = new PerformanceObserver((list) => {
    for (const entry of list.getEntries()) {
      // entry.duration counts the whole task; blocking time is the part over 50 ms
      const blocking = Math.max(0, entry.duration - 50)
      if (blocking > 100) {
        console.warn("long task", entry.duration, "ms, blocking", blocking, "ms")
      }
    }
  })
  observer.observe({ type: "longtask", buffered: true })
} catch (e) {
  console.log("longtask not supported")
}

// Chunked work with a portable yield between batches.
async function summarize(rows) {
  let total = 0
  for (let i = 0; i < rows.length; i++) {
    total += rows[i].value
    if (i % 200 === 199) {
      await new Promise((r) => setTimeout(r, 0)) // let input and paint run
    }
  }
  return total
}
